<x-layouts.app title="Reports"><section class="panel"><h2>Operational and financial reports</h2><p>Choose report, dates and download format.</p><form onsubmit="event.preventDefault();location.href='/reports/'+this.report.value+'/'+this.format.value+'?from='+this.from.value+'&to='+this.to.value"><label>Report<select name="report"><option value="deliveries">Daily meal delivery</option><option value="billing">Monthly billing</option><option value="collections">Employee collections</option><option value="outstanding">Outstanding balances</option><option value="cash-pending">Cash pending</option><option value="building-meals">Building-wise meal report</option><option value="payment-status">Paid / unpaid / partially paid</option><option value="building-outstanding">Building-wise outstanding</option><option value="revenue-summary">Daily revenue summary</option><option value="audit-log">Audit and correction log</option></select></label><label>From<input type="date" name="from" value="{{today()->startOfMonth()->format('Y-m-d')}}"></label><label>To<input type="date" name="to" value="{{today()->format('Y-m-d')}}"></label><label>Format<select name="format"><option value="xlsx">Excel</option><option value="pdf">PDF</option><option value="csv">CSV</option></select></label><button>Download</button></form></section></x-layouts.app>
